// ---------------------------------------------------------------------------
// Animation clips — frame sequences in public/characters/<id>/NNN.png
//
// Generated by scripts/extract-gif-frames.mjs. Frames are pre-extracted so
// playback is just a texture swap per tick: no GIF decoding at runtime.
//
// `fps` comes from the GIF's own per-frame delays. `width`/`height` are the
// on-disk PNG sizes, which for the first batch differ from the source GIF
// (those were re-exported through Unity at a smaller size) — so always trust
// the files, not the GIF header, or the sprites come out stretched.
//
// Provenance: see public/characters/README.md.
// ---------------------------------------------------------------------------

export interface DanceClip {
  id: string;
  frames: number;
  width: number;
  height: number;
  fps: number;
}

