export const CLIPS_BY_ID = new Map(DANCE_CLIPS.map((c) => [c.id, c]));

export function frameUrl(clipId: string, index: number) {
  return `/characters/${clipId}/${String(index).padStart(3, '0')}.png`;
}

/** One packed image holding every frame — see scripts/build-atlases.mjs */
export function atlasUrl(clipId: string) {
  return `/characters/${clipId}/atlas.png`;
}

/**
 * Grid layout of the atlas. Derived from the frame count rather than stored,
 * so this must stay identical to atlasGrid() in scripts/build-atlases.mjs or
 * the shader will sample the wrong cells.
 */
export function atlasGrid(frames: number) {
  const cols = Math.ceil(Math.sqrt(frames));
  const rows = Math.ceil(frames / cols);
  return { cols, rows };
}

export function getClip(id: string | undefined): DanceClip {
  return (id && CLIPS_BY_ID.get(id)) || DANCE_CLIPS[0];
}

/** Stable fallback so a player with no pick still looks consistent everywhere */
export function clipForPlayer(playerId: string): DanceClip {
  let h = 0;
  for (let i = 0; i < playerId.length; i++) {
    h = (h * 31 + playerId.charCodeAt(i)) % 9973;
  }
  return DANCE_CLIPS[h % DANCE_CLIPS.length];
}
